IF EXISTS(SELECT 1 FROM bi.OperacionReferencia o WHERE o.IdLote=@lote AND o.Total<>(SELECT SUM(d.Importe) FROM bi.DetalleReferencia d WHERE d.IdOperacion=o.IdOperacion)) THROW 78006,N'El detalle de referencia no cuadra con la cabecera.',1;
IF EXISTS(SELECT 1 FROM bi.OperacionReferencia o WHERE o.IdLote=@lote AND o.IdCliente IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bi.EntidadReferencia e WHERE e.IdEntidad=o.IdCliente AND e.Tipo='cliente' AND e.IdLote=@lote)) THROW 78007,N'Cliente de referencia inválido.',1;
IF EXISTS(SELECT 1 FROM bi.OperacionReferencia o WHERE o.IdLote=@lote AND o.IdProveedor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bi.EntidadReferencia e WHERE e.IdEntidad=o.IdProveedor AND e.Tipo='proveedor' AND e.IdLote=@lote)) THROW 78008,N'Proveedor de referencia inválido.',1;
IF EXISTS(SELECT 1 FROM(SELECT SUM(CASE WHEN Tipo=N'Salida' THEN -Cantidad ELSE Cantidad END) OVER(PARTITION BY IdProducto ORDER BY Fecha,IdMovimiento ROWS UNBOUNDED PRECEDING) Saldo FROM bi.MovimientoReferencia WHERE IdLote=@lote) s WHERE Saldo<0) THROW 78009,N'La evolución del saldo sintético presenta cantidades negativas.',1;
IF EXISTS(SELECT 1 FROM bi.OperacionReferencia WHERE IdLote=@lote AND (Fecha<'20260401' OR Fecha>='20261013' OR (Tipo IN('venta','cotizacion') AND (IdCliente IS NULL OR IdProveedor IS NOT NULL)) OR (Tipo='compra' AND (IdProveedor IS NULL OR IdCliente IS NOT NULL)))) THROW 78010,N'Operación sintética fuera del periodo o con tercero inválido.',1;
UPDATE bi.LoteReferencia SET Estado='Completo' WHERE IdLote=@lote;
COMMIT;
SELECT Tipo,COUNT(*) Cantidad FROM bi.OperacionReferencia WHERE IdLote=@lote GROUP BY Tipo;
